BEGIN;
SET LOCAL lock_timeout='5s';
CREATE TABLE IF NOT EXISTS public.university_fee_sources (
 id BIGSERIAL PRIMARY KEY,
 university_id integer NOT NULL REFERENCES public.universities(id),
 source_file varchar(180) NOT NULL,
 source_sheet varchar(100) NOT NULL,
 source_row integer NOT NULL,
 course_name varchar(255) NOT NULL,
 study_mode varchar(40) NOT NULL,
 fee_basis varchar(40) NOT NULL CHECK(fee_basis IN ('PER_YEAR','LISTED_COURSE_TOTAL','UNSPECIFIED_TOTAL')),
 listed_amount_paise integer NOT NULL CHECK(listed_amount_paise > 0),
 component_breakdown jsonb NOT NULL,
 duration varchar(100),
 eligibility varchar(100),
 review_status varchar(30) NOT NULL DEFAULT 'NEEDS_REVIEW' CHECK(review_status IN ('NEEDS_REVIEW','REVIEWED')),
 review_note text NOT NULL,
 loaded_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(source_file,source_sheet,source_row)
);
CREATE INDEX IF NOT EXISTS university_fee_source_lookup_idx ON public.university_fee_sources(university_id,study_mode,course_name);
ALTER TABLE public.university_fee_sources ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.university_fee_sources FROM PUBLIC,anon,authenticated;
REVOKE ALL ON SEQUENCE public.university_fee_sources_id_seq FROM PUBLIC,anon,authenticated;
ON CONFLICT(source_file,source_sheet,source_row) DO NOTHING;
COMMIT;